{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "AZD0837, a structurally related oral prodrug with a benzamidine-like moiety and proline scaffold, has mean absolute bioavailability 22–55% in healthy volunteers, directly supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Perindopril, an ethyl ester prodrug of a peptide-like ACE inhibitor, has absolute oral bioavailability about 75% in humans, supporting high F for the query's ester prodrug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "R-Desethyloxybutynin showed 62% oral bioavailability in healthy adults, a high-F human measurement with very high transfer score.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Telaprevir, a peptidomimetic with cyclohexyl and multiple amide bonds, demonstrates good oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Encainide in healthy subjects showed oral bioavailability 20–30%, at/above the threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Perindoprilat (S-9780) had 19% ± 7% bioavailability after oral perindopril in young healthy subjects, a borderline sub-20 value for active metabolite exposure after a prodrug.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a double prodrug (ethyl ester + hydroxyamidine) of a thrombin inhibitor. The closest structural analogue AZD0837 has absolute F 22–55% in humans; the ester prodrug perindopril has F ~75%; numerous other high-transfer human F measurements are ≥20%. The only sub-20 record (C36) reflects perindoprilat active metabolite after prodrug and is outweighed. Prediction: high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule in the provided evidence; reliance on close analogues.",
    "The query's F is near the 20% threshold; small methodological differences could shift the binary label.",
    "C36 measures active metabolite exposure after a prodrug rather than parent prodrug F, limiting its directness."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

